import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    g = [list(data[2 + i]) for i in range(r)]
    q = deque()
    fresh = 0
    for i in range(r):
        row = g[i]
        for j in range(c):
            if row[j] == '2':
                q.append((i, j))
            elif row[j] == '1':
                fresh += 1
    minutes = 0
    while q and fresh:
        minutes += 1
        for _ in range(len(q)):
            i, j = q.popleft()
            for ni, nj in ((i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)):
                if 0 <= ni < r and 0 <= nj < c and g[ni][nj] == '1':
                    g[ni][nj] = '2'
                    fresh -= 1
                    q.append((ni, nj))
    print(minutes if fresh == 0 else -1)

